fn clip(a: Vec<i8>, min: i8, max: i8) -> Vec<i8> {
    // Create a new vector to hold the clipped values
    let mut result = Vec::with_capacity(a.len());

    // Iterate through each element in the input vector
    for &value in &a {
        // Clip the value according to the bounds
        if value < min {
            result.push(min);
        } else if value > max {
            result.push(max);
        } else {
            result.push(value);
        }
    }

    // Return the resulting vector
    result
}